static BOOL Match(NSString*s,NSString*pattern){return [s isKindOfClass:NSString.class]&&[s rangeOfString:pattern options:NSRegularExpressionSearch].location!=NSNotFound;}
static BOOL Repo(NSString*s){return Match(s,@"^OrientLuna/OrTTS-[A-Za-z0-9._-]+$");}
