NSArray *OrTTSOwnRepositories(NSDictionary*r){if(![r isKindOfClass:NSDictionary.class]||[r[@"Code"] integerValue]!=200||![r[@"Data"] isKindOfClass:NSDictionary.class]||![r[@"Data"][@"Models"] isKindOfClass:NSArray.class])return nil;NSMutableArray*out=[NSMutableArray new];for(id m in r[@"Data"][@"Models"]){if(![m isKindOfClass:NSDictionary.class])continue;NSString*repo=[NSString stringWithFormat:@"%@/%@",m[@"Path"],m[@"Name"]];if(Repo(repo)&&![out containsObject:repo])[out addObject:repo];}return out;}
NSArray *OrTTSOwnManifestSources(NSString*repo,NSDictionary*r){if(!Repo(repo)||![r isKindOfClass:NSDictionary.class]||![r[@"Data"]isKindOfClass:NSDictionary.class]||[r[@"Code"] integerValue]!=200||![r[@"Data"][@"Files"] isKindOfClass:NSArray.class])return nil;NSMutableArray*out=[NSMutableArray new];for(NSDictionary*f in r[@"Data"][@"Files"]){if(![f isKindOfClass:NSDictionary.class])continue;NSString*p=f[@"Path"],*c=f[@"Revision"],*h=f[@"Sha256"];if(Path(p)&&([p isEqual:@"DOWNLOAD_MANIFEST.json"]||[p hasSuffix:@"/DOWNLOAD_MANIFEST.json"])&&Match(c,@"^[a-f0-9]{40}$")&&Match(h,@"^[a-f0-9]{64}$")&&[f[@"Size"] longLongValue]>0&&[f[@"Size"] longLongValue]<=2*1024*1024)[out addObject:@{@"id":repo,@"source_commit":c,@"manifest_path":p,@"manifest_sha256":h,@"manifest_url":[NSString stringWithFormat:@"%@%@/resolve/%@/%@",Root,repo,c,p],@"source":@"modelscope"}];}[out sortUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return [a[@"manifest_path"] compare:b[@"manifest_path"]];}];return out;}
static BOOL Selected(NSString*path,NSArray*patterns){for(id v in patterns){if(![v isKindOfClass:NSString.class])return NO;NSString*pattern=[NSRegularExpression escapedPatternForString:v];pattern=[pattern stringByReplacingOccurrencesOfString:@"\\*\\*" withString:@"\x01"];pattern=[pattern stringByReplacingOccurrencesOfString:@"\\*" withString:@"[^/]*"];pattern=[pattern stringByReplacingOccurrencesOfString:@"\x01" withString:@".*"];if(Match(path,[@"^" stringByAppendingFormat:@"%@$",pattern]))return YES;}return NO;}
NSDictionary *OrTTSNormalizeOwnModel(NSDictionary*source,NSData*data){@try{
 if(!data.length||data.length>2*1024*1024||![SHA(data)isEqual:source[@"manifest_sha256"]])return nil;NSDictionary*m=[NSJSONSerialization JSONObjectWithData:data options:0 error:nil];if(![m isKindOfClass:NSDictionary.class]||![m[@"schema"] isEqual:@"ortts-download-manifest-v1"]||![m[@"model_id"] isEqual:source[@"id"]]||!Match(m[@"revision"],@"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$"))return nil;
