 NSArray*files=m[@"files"];if(![files isKindOfClass:NSArray.class]||!files.count||files.count>256)return nil;NSMutableDictionary*sizes=[NSMutableDictionary new];long long total=0;for(NSDictionary*f in files){NSString*p=f[@"path"];id number=f[@"bytes"];if(![number isKindOfClass:NSNumber.class])return nil;long long n=[number longLongValue];if(!Path(p)||sizes[p]||!Match(f[@"sha256"],@"^[a-f0-9]{64}$")||n<0||n>8LL*1024*1024*1024)return nil;sizes[p]=number;total+=n;}if(total>8LL*1024*1024*1024||!sizes[@"native/model.gguf"]||!sizes[@"voices/female.f32"]||!sizes[@"voices/male.f32"])return nil;
 if([kind isEqual:@"liquidcodec"]&&(![@[@"base",@"expanded"]containsObject:decoder[@"variant"]]||!Path(decoder[@"manifest"])||![decoder[@"manifest"]hasSuffix:@"/runtime.json"]||!sizes[decoder[@"manifest"]]))return nil;
