 NSDictionary*rules=m[@"selection_rules"];for(NSString*k in @[@"common",@"P3",@"P5"])if(![rules[k]isKindOfClass:NSArray.class])return nil;
 NSDictionary*policy=m[@"research_policy"];BOOL p3Only=policy!=nil;if(p3Only&&(![policy[@"schema"]isEqual:@"ortts-ptq-lazy-qa-v1"]||[policy[@"expected_talker_matrices"]integerValue]!=196||![policy[@"training_steps"]isEqual:@0]||[m[@"speaker_dimension"]integerValue]!=1024||![kind isEqual:@"liquidcodec"]||!(([policy[@"expected_talker_type"]integerValue]==2&&[policy[@"lazy_import_scratch"]boolValue])||([policy[@"expected_talker_type"]integerValue]==8&&![policy[@"lazy_import_scratch"]boolValue]))))return nil;
 NSArray*variants=m[@"supported_variants"]?: (p3Only?@[@"P3"]:@[@"P3",@"P5"]);if(![variants isKindOfClass:NSArray.class]||!variants.count)return nil;NSMutableDictionary*out=[source mutableCopy];for(NSString*v in variants){if(![@[@"P3",@"P5"]containsObject:v]||(p3Only&&![v isEqual:@"P3"]))return nil;if([v isEqual:@"P3"]&&(!sizes[@"P3/predictor/config.json"]||!sizes[@"P3/predictor/talker_config.json"]||(!sizes[@"P3/predictor/predictor.gguf"]&&!sizes[@"P3/predictor/predictor.safetensors"])))return nil;NSMutableArray*patterns=[rules[@"common"]mutableCopy];[patterns addObjectsFromArray:rules[@"P5"]];if([v isEqual:@"P3"])[patterns addObjectsFromArray:rules[@"P3"]];long long n=0;for(NSString*p in sizes)if(Selected(p,patterns))n+=[sizes[p]longLongValue];out[[v stringByAppendingString:@"_bytes"]]=@(n);}
 NSMutableArray*voices=[NSMutableArray new];for(NSString*v in @[@"female",@"female_2",@"male",@"male_2"])if(sizes[[NSString stringWithFormat:@"voices/%@.f32",v]])[voices addObject:v];
 out[@"name"]=[NSString stringWithFormat:@"%@ · %@",m[@"display_name"]?:[source[@"id"]lastPathComponent],m[@"revision"]];out[@"revision"]=m[@"revision"];out[@"supported_variants"]=variants;out[@"voices"]=voices;out[@"decoder"]=kind;out[@"p3_only"]=@(p3Only);return OrTTSValidOwnCatalogEntry(out)?out:nil;
 }@catch(NSException*e){return nil;}}
NSArray *OrTTSMergeOwnCatalogs(NSArray*arrays){NSMutableArray*out=[NSMutableArray new];NSMutableSet*seen=[NSMutableSet new];for(NSArray*a in arrays)for(NSDictionary*m in a)if(OrTTSValidOwnCatalogEntry(m)&&![seen containsObject:Key(m)]&&out.count<64){[seen addObject:Key(m)];[out addObject:m];}return out;}
static NSData* Request(NSString*url,NSDictionary*body,NSError**error){NSMutableURLRequest*q=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];q.timeoutInterval=8;if(body){q.HTTPMethod=@"PUT";q.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:error];[q setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];}NSURLSessionConfiguration*c=NSURLSessionConfiguration.ephemeralSessionConfiguration;c.URLCredentialStorage=nil;c.HTTPCookieStorage=nil;c.HTTPShouldSetCookies=NO;c.timeoutIntervalForResource=12;NSURLSession*s=[NSURLSession sessionWithConfiguration:c];dispatch_semaphore_t done=dispatch_semaphore_create(0);__block NSData*data=nil;__block NSError*failure=nil;NSURLSessionDataTask*t=[s dataTaskWithRequest:q completionHandler:^(NSData*d,NSURLResponse*r,NSError*e){if(e)failure=e;else if(((NSHTTPURLResponse*)r).statusCode!=200||d.length>2*1024*1024||![@[@"modelscope.cn",@"www.modelscope.cn"]containsObject:r.URL.host]||![r.URL.scheme isEqual:@"https"])failure=[NSError errorWithDomain:@"OrTTSCatalog" code:1 userInfo:@{NSLocalizedDescriptionKey:@"目录HTTP或大小校验失败"}];else data=d;dispatch_semaphore_signal(done);}];[t resume];dispatch_semaphore_wait(done,DISPATCH_TIME_FOREVER);[s finishTasksAndInvalidate];if(error)*error=failure;return data;}
NSArray *OrTTSRefreshOwnCatalog(NSArray*previous,NSError**error){@try{NSDate*start=[NSDate date];NSMutableArray*repos=[NSMutableArray new],*found=[NSMutableArray new];for(NSInteger page=1;page<=4;page++){NSData*b=Request(API,@{@"Path":@"OrientLuna",@"PageNumber":@(page),@"PageSize":@50},error);if(!b)return nil;NSDictionary*r=[NSJSONSerialization JSONObjectWithData:b options:0 error:error];NSArray*a=OrTTSOwnRepositories(r);if(!a)return nil;for(NSString*p in a)if(![repos containsObject:p])[repos addObject:p];if(page*50>=[r[@"Data"][@"TotalCount"]integerValue])break;}
 NSMutableDictionary*cached=[NSMutableDictionary new];for(NSDictionary*m in previous)if(OrTTSValidOwnCatalogEntry(m))cached[Key(m)]=m;NSInteger scanned=0;for(NSString*repo in repos){if(++scanned>8||-[start timeIntervalSinceNow]>60)break;NSString*u=[NSString stringWithFormat:@"%@/%@/repo/files?Revision=master&Recursive=true",API,repo];NSData*b=Request(u,nil,nil);NSDictionary*r=b?[NSJSONSerialization JSONObjectWithData:b options:0 error:nil]:nil;NSInteger count=0;for(NSDictionary*source in OrTTSOwnManifestSources(repo,r)){if(++count>8||found.count>=32||-[start timeIntervalSinceNow]>60)break;NSDictionary*m=cached[Key(source)];if(!m){NSData*d=Request(source[@"manifest_url"],nil,nil);m=d?OrTTSNormalizeOwnModel(source,d):nil;}if(m)[found addObject:m];}}
